CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "AspNetRoles" (
    "Id" text NOT NULL,
    description text,
    "creationDate" timestamp without time zone NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

CREATE TABLE "City" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    CONSTRAINT "PK_City" PRIMARY KEY ("Id")
);

CREATE TABLE "EventType" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    CONSTRAINT "PK_EventType" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUsers" (
    "Id" text NOT NULL,
    "FirstName" text,
    "LastName" text,
    "CityId" integer,
    "Address" text,
    "PostalCode" text,
    "HasRequestedVenueManagerRole" boolean NOT NULL,
    "VenueManagerRequestDate" timestamp without time zone,
    "VenueManagerRequestReason" text,
    "VenueManagerRequestStatus" text,
    "HasRequestedEventManagerRole" boolean NOT NULL,
    "EventManagerRequestDate" timestamp without time zone,
    "EventManagerRequestReason" text,
    "EventManagerRequestStatus" text,
    "HasRequestedSuperOrganizerRole" boolean NOT NULL,
    "SuperOrganizerRequestDate" timestamp without time zone,
    "SuperOrganizerRequestReason" text,
    "SuperOrganizerRequestStatus" text,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUsers_City_CityId" FOREIGN KEY ("CityId") REFERENCES "City" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" character varying(128) NOT NULL,
    "ProviderKey" character varying(128) NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" character varying(128) NOT NULL,
    "Name" character varying(128) NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Venue" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    "Address" text,
    "CityId" integer NOT NULL,
    "PostalCode" text,
    "Phone" text,
    "VenueUrl" text,
    "SocialMediaUrl" text,
    "UserId" text,
    "imgUrl" text,
    CONSTRAINT "PK_Venue" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Venue_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Venue_City_CityId" FOREIGN KEY ("CityId") REFERENCES "City" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SubArea" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AreaName" text,
    "Width" numeric(18,2) NOT NULL,
    "Height" numeric(18,2) NOT NULL,
    "Top" numeric(18,2) NOT NULL,
    "Left" numeric(18,2) NOT NULL,
    "Rotate" numeric(18,2) NOT NULL,
    "Desc" text,
    "VenueId" integer NOT NULL,
    CONSTRAINT "PK_SubArea" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SubArea_Venue_VenueId" FOREIGN KEY ("VenueId") REFERENCES "Venue" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "VenueCategory" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VenueId" integer NOT NULL,
    "CategoryId" integer,
    CONSTRAINT "PK_VenueCategory" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VenueCategory_EventType_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "EventType" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_VenueCategory_Venue_VenueId" FOREIGN KEY ("VenueId") REFERENCES "Venue" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Event" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    "StartDateTime" timestamp without time zone NOT NULL,
    "EndTime" timestamp without time zone NOT NULL,
    "EventTypeId" integer NOT NULL,
    "VenueId" integer NOT NULL,
    "SubAreaId" integer,
    "ParentEventId" integer,
    "ImagePath" text,
    CONSTRAINT "PK_Event" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Event_EventType_EventTypeId" FOREIGN KEY ("EventTypeId") REFERENCES "EventType" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Event_Event_ParentEventId" FOREIGN KEY ("ParentEventId") REFERENCES "Event" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Event_SubArea_SubAreaId" FOREIGN KEY ("SubAreaId") REFERENCES "SubArea" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Event_Venue_VenueId" FOREIGN KEY ("VenueId") REFERENCES "Venue" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Seat" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "X" numeric(18,2) NOT NULL,
    "Y" numeric(18,2) NOT NULL,
    "Name" text,
    "Available" boolean NOT NULL,
    "SubAreaId" integer NOT NULL,
    CONSTRAINT "PK_Seat" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Seat_SubArea_SubAreaId" FOREIGN KEY ("SubAreaId") REFERENCES "SubArea" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Reservation" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text,
    "SeatId" integer NOT NULL,
    "EventId" integer NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "Duration" bigint NOT NULL,
    "IsPastReservation" boolean NOT NULL,
    "Attended" boolean,
    "Review" text,
    "Rating" integer,
    CONSTRAINT "PK_Reservation" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_Reservation_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Reservation_Event_EventId" FOREIGN KEY ("EventId") REFERENCES "Event" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Reservation_Seat_SeatId" FOREIGN KEY ("SeatId") REFERENCES "Seat" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_AspNetRoleClaims_RoleId" ON "AspNetRoleClaims" ("RoleId");

CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName");

CREATE INDEX "IX_AspNetUserClaims_UserId" ON "AspNetUserClaims" ("UserId");

CREATE INDEX "IX_AspNetUserLogins_UserId" ON "AspNetUserLogins" ("UserId");

CREATE INDEX "IX_AspNetUserRoles_RoleId" ON "AspNetUserRoles" ("RoleId");

CREATE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");

CREATE INDEX "IX_AspNetUsers_CityId" ON "AspNetUsers" ("CityId");

CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName");

CREATE INDEX "IX_Event_EventTypeId" ON "Event" ("EventTypeId");

CREATE INDEX "IX_Event_ParentEventId" ON "Event" ("ParentEventId");

CREATE INDEX "IX_Event_SubAreaId" ON "Event" ("SubAreaId");

CREATE INDEX "IX_Event_VenueId" ON "Event" ("VenueId");

CREATE INDEX "IX_Reservation_EventId" ON "Reservation" ("EventId");

CREATE INDEX "IX_Reservation_SeatId" ON "Reservation" ("SeatId");

CREATE INDEX "IX_Reservation_UserId" ON "Reservation" ("UserId");

CREATE INDEX "IX_Seat_SubAreaId" ON "Seat" ("SubAreaId");

CREATE INDEX "IX_SubArea_VenueId" ON "SubArea" ("VenueId");

CREATE INDEX "IX_Venue_CityId" ON "Venue" ("CityId");

CREATE INDEX "IX_Venue_UserId" ON "Venue" ("UserId");

CREATE INDEX "IX_VenueCategory_CategoryId" ON "VenueCategory" ("CategoryId");

CREATE INDEX "IX_VenueCategory_VenueId" ON "VenueCategory" ("VenueId");

