CREATE TABLE "NonSelectable" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SubAreaId" integer NOT NULL,
    "X" numeric NOT NULL,
    "Y" numeric NOT NULL,
    "Width" numeric NOT NULL,
    "Height" numeric NOT NULL,
    "ShapeType" text,
    "BackgroundColor" text,
    "Name" text,
    "Scene" boolean NOT NULL,
    CONSTRAINT "PK_NonSelectable" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_NonSelectable_SubArea_SubAreaId" FOREIGN KEY ("SubAreaId") REFERENCES "SubArea" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_NonSelectable_SubAreaId" ON "NonSelectable" ("SubAreaId");

