    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventId" integer NOT NULL,
    "ImagePath" text,
    "DisplayOrder" integer NOT NULL,
    CONSTRAINT "PK_EventImage" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EventImage_Event_EventId" FOREIGN KEY ("EventId") REFERENCES "Event" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_Event_OrganizerId" ON "Event" ("OrganizerId");

